// Free news sources: Google News RSS searches, Hacker News search RSS, and a few vendor/industry blogs.
// Edit this list to add or remove topics. One item per feed.
const gn = (q) => 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) + '&hl=en-US&gl=US&ceid=US:en';

const feeds = [
  { name: 'GN voice agents', url: gn('"voice agent" OR "voice AI" OR "AI voice agent" when:2d') },
  { name: 'GN voice platforms', url: gn('Vapi OR "Retell AI" OR ElevenLabs OR "Bland AI" OR Synthflow OR Deepgram OR Cartesia OR LiveKit when:3d') },
  { name: 'GN speech models', url: gn('"speech-to-speech" OR "realtime API" OR "text-to-speech" OR "speech recognition" AI when:3d') },
  { name: 'GN automation', url: gn('n8n OR "AI automation" OR "AI agents" OR "agentic AI" when:2d') },
  { name: 'GN regulation', url: gn('"AI voice" OR "AI calls" OR robocall TCPA OR FCC AI when:7d') },
  { name: 'HN voice', url: 'https://hnrss.org/newest?q=voice+agent+OR+%22voice+AI%22+OR+text-to-speech&points=15' },
  { name: 'HN automation', url: 'https://hnrss.org/newest?q=n8n+OR+%22AI+agents%22&points=40' },
  { name: 'n8n blog', url: 'https://blog.n8n.io/rss/' },
  { name: 'OpenAI news', url: 'https://openai.com/news/rss.xml' },
  { name: 'TechCrunch AI', url: 'https://techcrunch.com/category/artificial-intelligence/feed/' }
];

return feeds.map(f => ({ json: f }));

// Keep recent items only, dedupe by title, cap the list, and flatten to text for the LLM.
const MAX_AGE_HOURS = 72;
const MAX_ITEMS = 60;
const cutoff = Date.now() - MAX_AGE_HOURS * 3600 * 1000;

const seen = new Set();
const rows = [];

for (const it of $input.all()) {
  const j = it.json;
  if (!j.title || !j.link) continue; // skips feeds that errored
  const t = new Date(j.isoDate || j.pubDate || 0).getTime();
  if (t && t < cutoff) continue;
  const key = j.title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 80);
  if (seen.has(key)) continue;
  seen.add(key);
  const snippet = String(j.contentSnippet || j.content || '').replace(/\s+/g, ' ').trim().slice(0, 220);
  rows.push({ t, title: j.title.trim(), link: j.link, snippet });
}

rows.sort((a, b) => b.t - a.t);
const top = rows.slice(0, MAX_ITEMS);

const digest = top
  .map((r, i) => (i + 1) + '. ' + r.title + '\n   URL: ' + r.link + (r.snippet ? '\n   Note: ' + r.snippet : ''))
  .join('\n');

if (!top.length) {
  throw new Error('No recent items found in any feed. Check the Feed List node.');
}

return [{ json: { digest, count: top.length } }];

// Clean the writer's output into a Gmail-ready subject + HTML body
let html = String($input.first().json.output || '')
  .replace(/^\s*```(?:html)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

// Drop any chatter before the document starts
const start = html.search(/<!DOCTYPE html|<html/i);
if (start > 0) html = html.slice(start);

// Fallback: if the model ignored the format, still deliver the research as readable text
if (!/<html/i.test(html)) {
  const brief = String($('Research Agent').item.json.output || html);
  const esc = brief.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  html = '<html><head><title>Voice AI Daily</title></head><body style="font-family:Arial,sans-serif;max-width:640px;margin:auto;white-space:pre-wrap">' + esc + '</body></html>';
}

const match = html.match(/<title>([\s\S]*?)<\/title>/i);
let subject = match ? match[1].trim() : '';
if (!subject || subject.toUpperCase() === 'SUBJECT') {
  subject = 'Voice AI Daily - ' + $now.toFormat('LLL d');
}

return [{ json: { subject, html } }];
